import * as OurTypes from "../src/types";
import * as TestCommonJsonization from "./commonJsonization";

test("casts over an instance of Box", () => {
  const theBox =
    TestCommonJsonization.loadMinimalBox();

  expect(
    OurTypes.isItem(theBox)
  ).toStrictEqual(true);
  expect(
    OurTypes.asItem(theBox)
  ).toStrictEqual(theBox);

  expect(
    OurTypes.isBox(theBox)
  ).toStrictEqual(true);
  expect(
    OurTypes.asBox(theBox)
  ).toStrictEqual(theBox);
});

